    mu sync.Mutex
    cfg Config
    ring []T
    head, used int
    overflow []T
    overflowHead int
    base, next uint64
    overflowSince time.Time
    cursors map[*Cursor[T]]struct{}
    notify chan struct{}
    closed bool
