func (b *Buffer[T]) Append(items ...T) {
    if len(items) == 0 { return }
    b.mu.Lock()
    defer b.mu.Unlock()
    if b.closed || len(b.cursors) == 0 { return }
    b.expireLocked()
    if len(b.cursors) == 0 { return }
    if b.ring == nil { b.ring = make([]T, b.cfg.Capacity) }
    for len(items) > 0 && b.used < len(b.ring) {
        b.ring[(b.head+b.used)%len(b.ring)] = items[0]
        b.used++
        items = items[1:]
        b.next++
    }
    if len(items) > 0 {
        if b.overflowHead == len(b.overflow) { b.overflow = nil; b.overflowHead = 0 }
        if b.overflowSince.IsZero() { b.overflowSince = b.cfg.Clock.Now() }
