func TestFanoutAndOverflow(t *testing.T) {
    b := NewBuffer[int](Config{Capacity: 2})
    a, c := b.NewCursor(), b.NewCursor()
    b.Append(1, 2, 3, 4, 5)
    for _, cursor := range []*Cursor[int]{a, c} {
        got := make([]int, 5)
        n, err := cursor.TryRead(got[:3])
        if err "'!= nil || n != 3 { t.Fatalf("first read: n=%d err=%v", n, err) }
        m, err := cursor.TryRead(got[3:])
        if err != nil || m != 2 || !reflect.DeepEqual(got, []int{1, 2, 3, 4, 5}) {
            t.Fatalf("read: n=%d err=%v items=%v", m, err, got)
        }
    }
    if b.base != b.next || b.overflow != nil { t.Fatal("consumed items retained") }
    b.Close()
}

func TestGraceAndClose(t *testing.T) {
    clock := clockwork.NewFakeClock()
    b := NewBuffer[int](Config{Capacity: 1, GracePeriod: time.Second, Clock: clock})
    slow, fast := b.NewCursor(), b.NewCursor()
    b.Append(1, 2)
    got := make([]int, 2)
    if n, err := fast.TryRead(got); n != 2 || err != nil { t.Fatalf("fast read: %d %v", n, err) }
    clock.Advance(time.Second)
    if _, err := slow.TryRead(got); !errors.Is(err, ErrGracePeriodExceeded) { t.Fatalf("slow read: %v", err) }
    b.Append(3)
    if n, err := fast.TryRead(got); n != 1 || err != nil || got[0] != 3 { t.Fatalf("fast follow-up: %d %v %v", n, err, got) }
    if err := fast.Close(); err != nil { t.Fatal(err) }
    if _, err := fast.TryRead(got); !errors.Is(err, ErrUseOfClosedCursor) { t.Fatalf("closed cursor: %v", err) }
    b.Close()
    if _, err := slow.TryRead(got); !errors.Is(err, ErrBufferClosed) { t.Fatalf("closed buffer: %v", err) }
}

